    { p: 9, c1: 2, c2: 3 },
    { p: 10, c1: 4, c2: 5 },
    { p: 11, c1: 6, c2: 7 },
    { p: 12, c1: 8, c2: 9 },
    { p: 13, c1: 10, c2: 11 },
    { p: 14, c1: 12, c2: 13 }
];

// Define arrowhead for lines
let defs = draw.defs();
defs.marker('arrowhead', 8, 8, function(add) {
    add.path('M 0 0 L 8 4 L 0 8 z').fill('#999');
}).attr({ refX: 7, refY: 4, orient: 'auto' });

// Groups to manage drawing order (z-index)
const bgGroup = draw.group();
const fgGroup = draw.group();

function drawArrow(group, x1, y1, x2, y2) {
    let dx = x2 - x1, dy = y2 - y1;
    let L = Math.sqrt(dx*dx + dy*dy);
    let ux = dx/L, uy = dy/L;
    let sx = x1 + ux * 6, sy = y1 + uy * 6;
    let ex = x2 - ux * 16, ey = y2 - uy * 16;

    group.line(sx, sy, ex, ey).stroke({ width: 3, color: '#999', linecap: 'round' })
         .attr('marker-end', 'url(#arrowhead)');
}

// Draw static structural connections
merges.forEach(m => {
    let p = boxDefs.find(b => b.id === m.p);
    let c1 = boxDefs.find(b => b.id === m.c1);
    let c2 = boxDefs.find(b => b.id === m.c2);

    // Arrows from the top center of children pointing toward the bottom quarter-points of the parent
    let qOffset = (p.size * 24) / 4;
    drawArrow(bgGroup, c1.x, c1.y - 15, p.x - qOffset, p.y + 15);
    drawArrow(bgGroup, c2.x, c2.y - 15, p.x + qOffset, p.y + 15);

    // Merge labels perfectly halfway vertically
    bgGroup.text("merge").attr({ x: p.x, y: (p.y + c1.y) / 2 })
           .font({ size: 14, anchor: 'middle', family: 'sans-serif' }).fill('#555')
           .attr('dominant-baseline', 'central');
});

// Title text
bgGroup.text("initial sequence").attr({ x: 300, y: 415 })
       .font({ size: 16, anchor: 'middle', family: 'serif' });
bgGroup.text("sorted sequence").attr({ x: 300, y: 15 })
       .font({ size: 16, anchor: 'middle', family: 'serif' });

// Global app state
window.frames = [];
window.frameIdx = 0;
let playing = false;
let playInterval = null;
let stabilityMode = false;

window.toggle_stabilityToggle = function(on) {
    stabilityMode = on;
    renderFrame(frameIdx);
};

const codes = {
    sample: "while (!isEmpty(L) && !isEmpty(R)) {\n    if (peek(L) <= peek(R)) {\n        take(L);\n    } else {\n        take(R);\n    }\n}\nwhile (!isEmpty(L)) take(L);\nwhile (!isEmpty(R)) take(R);",
    buggy: "// BUG: using '<' instead of '<=' breaks stability!\nwhile (!isEmpty(L) && !isEmpty(R)) {\n    if (peek(L) < peek(R)) {\n        take(L);\n    } else {\n        take(R);\n    }\n}\nwhile (!isEmpty(L)) take(L);\nwhile (!isEmpty(R)) take(R);",
    starter: "// Write your merge logic here\n// Use: isEmpty(arr), peek(arr), take(arr)\n"
};

window.setTab = function(name) {
    document.getElementById('mergeImplementationCode').value = codes[name];
    document.querySelectorAll('.ce-tabs button').forEach(b => b.classList.remove('active'));
    document.getElementById('tab-' + name).classList.add('active');
};
setTab('sample');

window.goTo = function(i) {
    if(frames.length === 0) return;
    if(i < 0) i = 0;
    if(i >= frames.length) i = frames.length - 1;
    frameIdx = i;
    renderFrame(frameIdx);
};

window.togglePlay = function() {
    playing = !playing;
    document.getElementById('ce-play').innerText = playing ? 'Pause' : 'Play';
    if(playing) {
        if(frameIdx >= frames.length - 1) goTo(0);
        playInterval = setInterval(() => {
            if(frameIdx < frames.length - 1) {
                goTo(frameIdx + 1);
            } else {
                togglePlay();
            }
        }, 400); // 400ms per operation ensures it's readable
    } else {
        clearInterval(playInterval);
    }
};

function renderFrame(idx) {
    fgGroup.clear();
    if(!frames || frames.length === 0) return;

    let frame = frames[idx];
    let state = frame.state;
    let active = frame.active_merge || [];
    let highlighted = frame.indices || [];

    // Render every box for this state
    boxDefs.forEach(b => {
        let boxItems = state[b.id] || [];

        let isDest = active[2] === b.id;
        let isSource = active[0] === b.id || active[1] === b.id;

        let strokeColor = '#888';
        let strokeWidth = 1;
        let fillColor = '#e2e2e2';

        // Highlight active source arrays and destination array
        if (isDest) { strokeColor = '#2ca02c'; strokeWidth = 2; fillColor = '#eaffea'; }
        else if (isSource) { strokeColor = '#ff7f0e'; strokeWidth = 2; fillColor = '#ffeee0'; }

        // Highlight specifically interacting elements (peek or take)
        if (highlighted.includes(b.id)) {
            strokeColor = '#d62728';
            strokeWidth = 3;
        }

        let w = b.size * 24;
        let h = 30;
        let bx = b.x - w / 2;
        let by = b.y - h / 2;

        // Draw container
        fgGroup.rect(w, h).attr({ x: bx, y: by })
            .fill(fillColor).stroke({ color: strokeColor, width: strokeWidth, linejoin: 'round' });

        // Draw elements inside container
        boxItems.forEach((item, k) => {
            let color = stabilityMode ? (item.color || '#000') : '#000';
            let fontW = stabilityMode && color !== '#000' ? 'bold' : 'normal';

            fgGroup.text(String(item.val))
                .attr({ x: bx + k * 24 + 12, y: by + 15 })
                .font({ size: 16, anchor: 'middle', weight: fontW, family: 'sans-serif' })
                .attr('dominant-baseline', 'central')
                .fill(color);
        });
    });

    document.getElementById('ce-message').innerText = frame.message || '';
    document.getElementById('ce-counter').innerText = (idx + 1) + ' / ' + frames.length;
}

let workerObj = null;

window.runWorker = function() {
    if(playing) togglePlay();
    if(workerObj) workerObj.terminate();

    let btn = document.getElementById('ce-run');
    btn.disabled = true;
    btn.innerText = 'Running...';

    let statusEl = document.getElementById('ce-status');
    statusEl.innerText = 'Running...';
    statusEl.style.color = '#555';

    let code = document.getElementById('mergeImplementationCode').value;
    let inputStr = document.getElementById('mergeImplementationInput').value;

    // A secure worker Blob is created to evaluate user code purely synchronously.
    const workerScript = `
onmessage = function(e) {
    let code = e.data.code;
    let inputStr = e.data.inputStr;
    try {
        let initVals = inputStr.split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n));
        if(initVals.length !== 8) throw new Error("Input must have exactly 8 numbers separated by commas.");

        // Automatically assign tracking IDs and highlight colors to duplicated values
        let firstDup = null;
        let seen = new Set();
        for (let v of initVals) {
            if (seen.has(v)) { firstDup = v; break; }
            seen.add(v);
        }
        let cIdx = 0;

        let state = Array.from({length: 15}, () => []);
        for (let i = 0; i < 8; i++) {
            let color = '#000';
            if (initVals[i] === firstDup) {
                if (cIdx === 0) color = '#1f77b4'; // Original left instance (Blue)
                else if (cIdx === 1) color = '#d62728'; // Original right instance (Red)
                cIdx++;
            }
            state[i].push({ val: initVals[i], id: i, color: color });
        }

        let frames = [];
        let opCount = 0;
        const MAX_OPS = 2000;
        let currentL = null, currentR = null, currentDest = null;

        function saveFrame(kind, indices, msg) {
            frames.push({
                kind: kind,
                state: JSON.parse(JSON.stringify(state)), // Deep clone data structural snapshot
                indices: indices,
                active_merge: [currentL, currentR, currentDest],
                message: msg
            });
        }

        saveFrame('init', [], 'Initial state loaded');

        // Controlled API exposure
        function isEmpty(arr) {
            opCount++;
            if(opCount > MAX_OPS) throw new Error("Timeout: Execution ran too long, check for infinite loops.");
            return arr.head >= arr.items.length;
        }

        function peek(arr) {
            opCount++;
            if(opCount > MAX_OPS) throw new Error("Timeout: Execution ran too long.");
            if(isEmpty(arr)) throw new Error("peek() called on an empty sequence (" + arr.name + ")");
            let val = arr.items[arr.head].val;
            saveFrame('peek', [arr.id], 'peek ' + arr.name + ' → ' + val);
            return val;
        }

        function take(arr) {
            opCount++;
            if(opCount > MAX_OPS) throw new Error("Timeout: Execution ran too long.");
            if(isEmpty(arr)) throw new Error("take() called on an empty sequence (" + arr.name + ")");
            let item = arr.items[arr.head];
            arr.head++;
            arr.dest.items.push(item);
            saveFrame('take', [arr.id, arr.dest.id], 'take from ' + arr.name + ' → ' + item.val);
            return item.val;
        }

        // Dynamically compile user trace logic mapping onto safe internal wrappers
        let user_merge = new Function('L', 'R', 'isEmpty', 'peek', 'take', code);

        function doMerge(l_id, r_id, dest_id) {
            currentL = l_id; currentR = r_id; currentDest = dest_id;
            let L = { id: l_id, items: state[l_id], head: 0, dest: { id: dest_id, items: state[dest_id] }, name: 'L' };
            let R = { id: r_id, items: state[r_id], head: 0, dest: { id: dest_id, items: state[dest_id] }, name: 'R' };

            user_merge(L, R, isEmpty, peek, take);

            if (L.head < L.items.length || R.head < R.items.length) {
                throw new Error("Merge routine completed before consuming all available elements.");
            }

            currentL = null; currentR = null; currentDest = null;
            saveFrame('merge_done', [dest_id], 'Merge complete into sorted run.');
        }

        // Run the 7 static merges that compose an 8-element bottom-up merge sort
        doMerge(0, 1, 8);
        doMerge(2, 3, 9);
        doMerge(4, 5, 10);
        doMerge(6, 7, 11);
        doMerge(8, 9, 12);
        doMerge(10, 11, 13);
        doMerge(12, 13, 14);

        let success = true;
        let stabilityIntact = true;
        let finalArr = state[14];

        if (finalArr.length !== 8) {
            success = false;
        } else {
            for (let i = 1; i < 8; i++) {
                if (finalArr[i-1].val > finalArr[i].val) success = false;
                if (finalArr[i-1].val === finalArr[i].val && finalArr[i-1].id > finalArr[i].id) stabilityIntact = false;
            }
        }

        postMessage({ type: 'done', frames: frames, success: success, stabilityIntact: stabilityIntact });

    } catch(err) {
        postMessage({ type: 'error', error: err.message });
    }
};
    `;

    let blob = new Blob([workerScript], { type: 'application/javascript' });
    workerObj = new Worker(URL.createObjectURL(blob));

    let timeoutId = setTimeout(() => {
        workerObj.terminate();
        finishWorkerError("Execution timed out. Check for infinite while loops.");
    }, 1500);

    workerObj.onmessage = function(e) {
        clearTimeout(timeoutId);
        btn.disabled = false;
        btn.innerText = 'Run';

        if (e.data.type === 'error') {
            finishWorkerError(e.data.error);
        } else {
            frames = e.data.frames;
            let msg = '';
            let color = '';
            if (e.data.success) {
                if (!e.data.stabilityIntact) {
                    msg = 'Sorted, but Unstable! (Elements swapped relative order)';
                    color = '#d62728'; // Red
                } else {
                    msg = 'Success! Correct and stable.';
                    color = '#2ca02c'; // Green
                }
            } else {
                msg = 'Wrong Answer (Resulting array not properly sorted)';
                color = '#ff7f0e'; // Orange
            }

            statusEl.innerText = msg;
            statusEl.style.color = color;

            goTo(0);
        }
    };

    workerObj.postMessage({ code: code, inputStr: inputStr });
};

function finishWorkerError(errMsg) {
    document.getElementById('ce-run').disabled = false;
    document.getElementById('ce-run').innerText = 'Run';
    document.getElementById('ce-status').innerText = 'Code Error / Incomplete';
    document.getElementById('ce-status').style.color = '#d62728';

    if(!frames) frames = [];
    let stateCopy = frames.length > 0 ? JSON.parse(JSON.stringify(frames[frames.length-1].state)) : Array.from({length: 15}, () => []);
    frames.push({
        kind: 'error',
        state: stateCopy,
        indices: [],
        active_merge: [],
        message: 'Error: ' + errMsg
    });
    goTo(frames.length - 1);
}

const steps = [
    {
        title: "The Merge Process",
        narration: "Merge sort works bottom-up. It treats each element as a sorted run of length 1, then merges adjacent pairs into sorted runs of length 2, 4, and finally 8.",
        state: { stability: false }
    },
    {
        title: "Algorithm Stability",
        narration: "Notice the two '2's. A stable sort keeps them in their original order. Using '<=' instead of '<' in the merge condition guarantees the left '2' is taken first when they tie. Try running the buggy code to see stability break!",
        state: { stability: true }
    }
];

let currentStep = 0;
window.applyStep = function(i) {
    if(i < 0) i = 0;
    if(i >= steps.length) i = steps.length - 1;
    currentStep = i;

    document.getElementById('demoNarration').innerText = steps[i].narration;
    document.getElementById('stepLabel').innerText = (i + 1) + " / " + steps.length;

    let isStab = steps[i].state.stability;
    document.getElementById('stabilityToggleInput').checked = isStab;
    stabilityMode = isStab;

    if (i === 1) {
        setTab('buggy');
    } else {
        setTab('sample');
    }

    runWorker();
};

window.prevStep = function() { applyStep(currentStep - 1); };
window.nextStep = function() { applyStep(currentStep + 1); };

// Initialize demo
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Merge sort builds a sorted array from the bottom up by repeatedly merging pairs of smaller, already-sorted subarrays into larger sorted runs.
KEY INSIGHT (what students should walk away understanding): Merging two sorted sequences takes only linear time by comparing their front elements; repeating this in a tree structure sorts the entire array.
DEMO STEPS: 2 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Merge sort builds a sorted array from the bottom up by repeatedly merging pairs of smaller, already-sorted subarrays into larger sorted runs.",
  "figureType": "diagram",
  "elements": [
    "Bottom rank: 8 single-element gray squares containing 5, 2, 4, 7, 1, 3, 2, 6",
    "Label 'initial sequence' below the bottom rank",
    "Second rank: 4 two-element gray rectangles containing 2 5, 4 7, 1 3, 2 6",
    "Third rank: 2 four-element gray rectangles containing 2 4 5 7, 1 2 3 6",
    "Top rank: 1 eight-element gray rectangle containing 1 2 2 3 4 5 6 7",
    "Label 'sorted sequence' above the top rank",
    "Thick gray diagonal arrows pointing from each child block to its parent block",
    "Labels 'merge' positioned near the pairs of arrows"
  ],
  "interactions": [
    {
      "id": "stabilityToggle",
      "type": "toggle",
      "label": "Duplicate highlighting",
      "options": [
        "Standard",
        "Highlight duplicates"
      ],
      "default": "Standard",
      "teaches": "By visually distinguishing the two '2's, we can see if the algorithm is stable—that is, whether the '2' that started on the left remains on the left in the final sorted array."
    },
    {
      "id": "mergeImplementation",
      "type": "code_editor",
      "label": "Merge Routine",
      "teaches": "The merge step operates by repeatedly picking the smaller of the front elements from two already-sorted arrays (L and R), resulting in a single combined sorted array.",
      "entry_point": "merge(L, R)",
      "api": [
        {
          "op": "isEmpty(arr)",
          "does": "returns true if the source array (L or R) has no remaining elements"
        },
        {
          "op": "peek(arr)",
          "does": "returns the value of the front element of source array L or R"
        },
        {
          "op": "take(arr)",
          "does": "removes the front element from L or R and appends it to the active destination box"
        }
      ],
      "frame": "Highlights the currently active pair of source boxes and their destination box; visually moves the taken element from the source up to the next available slot in the destination box.",
      "input": {
        "label": "Initial array",
        "default": "5, 2, 4, 7, 1, 3, 2, 6"
      },
      "sample_code": "while (!isEmpty(L) && !isEmpty(R)) {\n    if (peek(L) <= peek(R)) {\n        take(L);\n    } else {\n        take(R);\n    }\n}\nwhile (!isEmpty(L)) take(L);\nwhile (!isEmpty(R)) take(R);",
      "buggy_code": "// BUG: using '<' instead of '<=' breaks stability!\nwhile (!isEmpty(L) && !isEmpty(R)) {\n    if (peek(L) < peek(R)) {\n        take(L);\n    } else {\n        take(R);\n    }\n}\nwhile (!isEmpty(L)) take(L);\nwhile (!isEmpty(R)) take(R);",
      "success_check": "Every parent block is fully populated in sorted order, and the top block contains the fully sorted array."
    }
  ],
  "demo_steps": [
    {
      "title": "The Merge Process",
      "narration": "Merge sort works bottom-up. It treats each element as a sorted run of length 1, then merges adjacent pairs into sorted runs of length 2, 4, and finally 8.",
      "state": {
        "stabilityToggle": "Standard"
      }
    },
    {
      "title": "Algorithm Stability",
      "narration": "Notice the two '2's. A stable sort keeps them in their original order. Using '<=' instead of '<' in the merge condition guarantees the left '2' is taken first when they tie. Try running the buggy code to see stability break!",
      "state": {
        "stabilityToggle": "Highlight duplicates"
      }
    }
  ],
  "keyInsight": "Merging two sorted sequences takes only linear time by comparing their front elements; repeating this in a tree structure sorts the entire array.",
  "reconstructionNotes": "Layout as a 4-level tree of gray rectangles. Box widths must physically scale with the number of elements they contain (e.g. rank 2 boxes are twice as wide as rank 1 boxes). The generator should initially draw the higher-rank boxes as empty slots; they will populate dynamically as the code_editor's take() operations execute. When 'Highlight duplicates' is active, color the first '2' (from index 1) blue and the second '2' (from index 6) red throughout all levels to track their movement."
}

