defs.marker('arrowhead', 12, 12, function(add) {
    add.path('M 0 0 L 10 5 L 0 10 z').fill('#888');
}).attr({ refX: 8, refY: 5, orient: 'auto' });

// Groups to manage drawing order (z-index)
const bgGroup = draw.group();
const fgGroup = draw.group();

function drawArrow(group, x1, y1, x2, y2) {
    let dx = x2 - x1, dy = y2 - y1;
    let L = Math.sqrt(dx*dx + dy*dy);
    let ux = dx/L, uy = dy/L;
    let sx = x1 + ux * 8, sy = y1 + uy * 8;
    let ex = x2 - ux * 20, ey = y2 - uy * 20;

    group.line(sx, sy, ex, ey).stroke({ width: 5, color: '#888', linecap: 'round' })
         .attr('marker-end', 'url(#arrowhead)');
}

