        if (highlighted.includes(b.id)) {
            strokeColor = '#d62728';
            strokeWidth = 3;
        }

        let w = b.size * 24;
        let h = 30;
        let bx = b.x - w / 2;
        let by = b.y - h / 2;

        // Draw container
        fgGroup.rect(w, h).attr({ x: bx, y: by })
            .fill(fillColor).stroke({ color: strokeColor, width: strokeWidth, linejoin: 'round' });

        // Draw elements inside container
        boxItems.forEach((item, k) => {
            let color = stabilityMode ? (item.color || '#000') : '#000';
            let fontW = stabilityMode && color !== '#000' ? 'bold' : 'normal';

            fgGroup.text(String(item.val))
                .attr({ x: bx + k * 24 + 12, y: by + 16 })
                .font({ size: 16, anchor: 'middle', weight: fontW, family: 'serif' })
                .attr('dominant-baseline', 'central')
                .fill(color);
        });
    });

    document.getElementById('ce-message').innerText = frame.message || '';
    document.getElementById('ce-counter').innerText = (idx + 1) + ' / ' + frames.length;
}

let workerObj = null;

window.runWorker = function(jumpToLast = false) {
    if(playing) togglePlay();
    if(workerObj) workerObj.terminate();

    let btn = document.getElementById('ce-run');
    btn.disabled = true;
    btn.innerText = 'Running...';

    let statusEl = document.getElementById('ce-status');
    statusEl.innerText = 'Running...';
    statusEl.style.color = '#555';

    let code = document.getElementById('mergeImplementationCode').value;
    let inputStr = document.getElementById('mergeImplementationInput').value;

    // A secure worker Blob is created to evaluate user code purely synchronously.
    const workerScript = `
onmessage = function(e) {
    let code = e.data.code;
    let inputStr = e.data.inputStr;
    try {
        let initVals = inputStr.split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n));
        if(initVals.length !== 8) throw new Error("Input must have exactly 8 numbers separated by commas.");

        // Automatically assign tracking IDs and highlight colors to duplicated values
        let firstDup = null;
        let seen = new Set();
        for (let v of initVals) {
            if (seen.has(v)) { firstDup = v; break; }
            seen.add(v);
        }
        let cIdx = 0;

        let state = Array.from({length: 15}, () => []);
        for (let i = 0; i < 8; i++) {
            let color = '#000';
            if (initVals[i] === firstDup) {
                if (cIdx === 0) color = '#1f77b4'; // Original left instance (Blue)
                else if (cIdx === 1) color = '#d62728'; // Original right instance (Red)
                cIdx++;
            }
            state[i].push({ val: initVals[i], id: i, color: color });
        }

        let frames = [];
        let opCount = 0;
        const MAX_OPS = 2000;
        let currentL = null, currentR = null, currentDest = null;

        function saveFrame(kind, indices, msg) {
            frames.push({
                kind: kind,
                state: JSON.parse(JSON.stringify(state)), // Deep clone data structural snapshot
                indices: indices,
                active_merge: [currentL, currentR, currentDest],
                message: msg
            });
        }

        saveFrame('init', [], 'Initial state loaded');

        // Controlled API exposure
        function isEmpty(arr) {
            opCount++;
            if(opCount > MAX_OPS) throw new Error("Timeout: Execution ran too long, check for infinite loops.");
            return arr.head >= arr.items.length;
        }

        function peek(arr) {
            opCount++;
            if(opCount > MAX_OPS) throw new Error("Timeout: Execution ran too long.");
            if(isEmpty(arr)) throw new Error("peek() called on an empty sequence (" + arr.name + ")");
            let val = arr.items[arr.head].val;
            saveFrame('peek', [arr.id], 'peek ' + arr.name + ' → ' + val);
            return val;
        }

        function take(arr) {
            opCount++;
            if(opCount > MAX_OPS) throw new Error("Timeout: Execution ran too long.");
            if(isEmpty(arr)) throw new Error("take() called on an empty sequence (" + arr.name + ")");
            let item = arr.items[arr.head];
            arr.head++;
            arr.dest.items.push(item);
            saveFrame('take', [arr.id, arr.dest.id], 'take from ' + arr.name + ' → ' + item.val);
            return item.val;
        }

        // Dynamically compile user trace logic mapping onto safe internal wrappers
        let user_merge = new Function('L', 'R', 'isEmpty', 'peek', 'take', code);

        function doMerge(l_id, r_id, dest_id) {
            currentL = l_id; currentR = r_id; currentDest = dest_id;
            let L = { id: l_id, items: state[l_id], head: 0, dest: { id: dest_id, items: state[dest_id] }, name: 'L' };
            let R = { id: r_id, items: state[r_id], head: 0, dest: { id: dest_id, items: state[dest_id] }, name: 'R' };

            user_merge(L, R, isEmpty, peek, take);

            if (L.head < L.items.length || R.head < R.items.length) {
                throw new Error("Merge routine completed before consuming all available elements.");
            }

            currentL = null; currentR = null; currentDest = null;
            saveFrame('merge_done', [dest_id], 'Merge complete into sorted run.');
        }

        // Run the 7 static merges that compose an 8-element bottom-up merge sort
        doMerge(0, 1, 8);
        doMerge(2, 3, 9);
        doMerge(4, 5, 10);
        doMerge(6, 7, 11);
        doMerge(8, 9, 12);
        doMerge(10, 11, 13);
        doMerge(12, 13, 14);

        let success = true;
        let stabilityIntact = true;
        let finalArr = state[14];

        if (finalArr.length !== 8) {
            success = false;
        } else {
            for (let i = 1; i < 8; i++) {
                if (finalArr[i-1].val > finalArr[i].val) success = false;
                if (finalArr[i-1].val === finalArr[i].val && finalArr[i-1].id > finalArr[i].id) stabilityIntact = false;
            }
        }

        postMessage({ type: 'done', frames: frames, success: success, stabilityIntact: stabilityIntact });

    } catch(err) {
        postMessage({ type: 'error', error: err.message });
    }
};
    `;

    let blob = new Blob([workerScript], { type: 'application/javascript' });
    workerObj = new Worker(URL.createObjectURL(blob));

    let timeoutId = setTimeout(() => {
        workerObj.terminate();
        finishWorkerError("Execution timed out. Check for infinite while loops.");
    }, 1500);

    workerObj.onmessage = function(e) {
        clearTimeout(timeoutId);
        btn.disabled = false;
        btn.innerText = 'Run';

        if (e.data.type === 'error') {
            finishWorkerError(e.data.error);
        } else {
            frames = e.data.frames;
            let msg = '';
            let color = '';
            if (e.data.success) {
                if (!e.data.stabilityIntact) {
                    msg = 'Sorted, but Unstable! (Elements swapped relative order)';
                    color = '#d62728'; // Red
                } else {
                    msg = 'Success! Correct and stable.';
                    color = '#2ca02c'; // Green
                }
            } else {
                msg = 'Wrong Answer (Resulting array not properly sorted)';
                color = '#ff7f0e'; // Orange
            }

            statusEl.innerText = msg;
            statusEl.style.color = color;

            if (jumpToLast) {
                goTo(frames.length - 1);
            } else {
                goTo(0);
            }

            if (!initialRenderDone) {
                window.__markRendered();
                initialRenderDone = true;
            }
        }
    };

    workerObj.postMessage({ code: code, inputStr: inputStr });
};

function finishWorkerError(errMsg) {
    document.getElementById('ce-run').disabled = false;
    document.getElementById('ce-run').innerText = 'Run';
    document.getElementById('ce-status').innerText = 'Code Error / Incomplete';
    document.getElementById('ce-status').style.color = '#d62728';

    if(!frames) frames = [];
    let stateCopy = frames.length > 0 ? JSON.parse(JSON.stringify(frames[frames.length-1].state)) : Array.from({length: 15}, () => []);
    frames.push({
        kind: 'error',
        state: stateCopy,
        indices: [],
        active_merge: [],
        message: 'Error: ' + errMsg
    });
    goTo(frames.length - 1);

    if (!initialRenderDone) {
        window.__markRendered();
        initialRenderDone = true;
    }
}

const steps = [
    {
        title: "The Merge Process",
        narration: "Merge sort works bottom-up. It treats each element as a sorted run of length 1, then merges adjacent pairs into sorted runs of length 2, 4, and finally 8.",
        state: { stability: false }
    },
    {
        title: "Algorithm Stability",
        narration: "Notice the two '2's. A stable sort keeps them in their original order. Using '<=' instead of '<' in the merge condition guarantees the left '2' is taken first when they tie. Try running the buggy code to see stability break!",
        state: { stability: true }
    }
];

let currentStep = 0;
window.applyStep = function(i) {
    if(i < 0) i = 0;
    if(i >= steps.length) i = steps.length - 1;
    currentStep = i;

    document.getElementById('demoNarration').innerText = steps[i].narration;
    document.getElementById('stepLabel').innerText = (i + 1) + " / " + steps.length;

    let isStab = steps[i].state.stability;
    document.getElementById('stabilityToggleInput').checked = isStab;
    stabilityMode = isStab;

    if (i === 1) {
        setTab('buggy');
    } else {
        setTab('sample');
    }

    // Auto-run and jump straight to the end state for educational clarity on step switch
    runWorker(true);
};

window.prevStep = function() { applyStep(currentStep - 1); };
window.nextStep = function() { applyStep(currentStep + 1); };

// Initialize demo (will internally invoke runWorker(true) and then call __markRendered)
applyStep(0);
// @FIGURE_CODE_END

